conceptCode:
total = 0
for x in range(1, 6):
    if x % 2 == 1:
        total += x
print(total)

solution:
a, b = map(int, input().split())
total = 0
for x in range(a, b + 1):
    if x % 2 == 0:
        total += x
print(total)

example.code:
a, b = map(int, input().split())
# range의 끝값은 포함되지 않아서, b까지 보려면 b + 1까지 가야 해요.
for number in range(a, b + 1):
    if number % 3 == 0:
        print(number)

practice.solution:
a = int(input())
b = int(input())
blue = 0
white = 0
for ticket in range(a, b + 1):
    if ticket % 2 == 0:
        blue += ticket
    else:
        white += ticket
print(blue, white)
